import {blocksFor,scheduleClock} from './core/sessions.js';
import {effectiveCourses,readOverrides} from './core/overrides.js';
import {currentSchool} from './core/schools.js';
import './adapters/universal.js';
import {setupDialogNavigation} from './core/dialogs.js';
import {COLORS,DEFAULT_TIMES,dateKey,monday,addDays,weekAt,parseWeeks,validateCourse,validateSettings,conflicts,coursesFor,toICS} from './core/model.js';
import {loadState,saveState,emptyState,rawBackup,migrateSchoolTimes} from './core/storage.js';
import {importData} from './adapters/registry.js';
import './adapters/zfsoft.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const DAYS=['周一','周二','周三','周四','周五','周六','周日'];
let state,storageError='',overrideError='';try{migrateSchoolTimes();state=loadState();}catch(e){state=emptyState();storageError=e.message;}
let week=Math.max(1,Math.min(state.settings.totalWeeks,weekAt(state.settings.startDate))),view='week',pendingImport=null,installEvent=null,toastTimer;
const native=!!window.CourseCompass;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function commit(next){if(storageError)throw Error(storageError);state=saveState(next);render();syncNativeCompanion();}
const dialogs=setupDialogNavigation({onRootBack:()=>{if(view==='week')return false;setView('week');return true;}});
function showDialog(id){dialogs.open(id,{nested:Boolean(dialogs.top())});}
function ask(title,body,action){$('#confirm-title').textContent=title;$('#confirm-body').textContent=body;$('#confirm-yes').onclick=()=>{try{action();$('#confirm-dialog').close();}catch(e){toast(e.message);}};showDialog('#confirm-dialog');}
function shortDate(d){return `${d.getMonth()+1}月${d.getDate()}日`;}
function periodLabel(course){return '第'+course.start+(course.end===course.start?'':'–'+course.end)+'节';}
function includesSession(block,session){return block.id===session.id&&block.day===session.day&&session.period>=block.start&&session.period<=block.end;}
function displayCourses(courses=state.courses){try{const result=effectiveCourses(courses,state.settings,readOverrides(),currentSchool().id);overrideError='';return result;}catch(error){overrideError=error.message;return courses;}}
function render(){
 const effective=displayCourses(),actual=weekAt(state.settings.startDate),today=(new Date().getDay()+6)%7+1,todayCourses=blocksFor(effective,actual,today,state.settings.times),weekCourses=blocksFor(effective,week,undefined,state.settings.times);
 const now=new Date(),mins=now.getHours()*60+now.getMinutes();
 const clock=scheduleClock(effective,state.settings,now),upcoming=clock.current[0]||clock.next[0];
 $('#today-date').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(now);
 $('#term-label').textContent=state.settings.term==='我的学期'?'MY CAMPUS, MY PACE':state.settings.term;
 $('#summary').innerHTML=`<div class="stat"><div class="stat-label">${week===actual?'本周课程':'所选周课程'}<span>▦</span></div><div class="stat-value">${weekCourses.length}<small>节安排</small></div><div class="stat-bottom">按上课时段统计</div></div><div class="stat"><div class="stat-label">今日安排<span>◷</span></div><div class="stat-value">${todayCourses.length}<small>节安排</small></div><div class="stat-bottom">${DAYS[today-1]}</div></div><div class="stat accent"><div class="stat-label">${clock.current.length?'正在上课':clock.onBreak?'课间 · 下一节':upcoming?'接下来的课程':'今日节奏'}<span>↗</span></div><div class="stat-value next-value">${upcoming?esc('第'+upcoming.period+'节 · '+upcoming.name):(todayCourses.length?'今天的课已结束':'留一点自由时间')}</div></div>`;
 const notices=[];if(storageError)notices.push(storageError);if(overrideError)notices.push(overrideError);if(state.demo)notices.push('正在查看示例课表，课程和作息仅用于演示。');if(!state.courses.length)notices.push('先在「学期设置」确认第一周日期和学校作息，课表周次才会准确。');if(actual<1||actual>state.settings.totalWeeks)notices.push('今天不在设定的学期范围内，请检查第一周日期。');const collisions=conflicts(state.courses);if(collisions.length)notices.push(`课表有 ${collisions.length} 组课程时间重叠，请在课程管理中核对。`);
 $('#status-banner').hidden=!notices.length;$('#status-banner').innerHTML=notices.map(esc).join(' ')+' <button id="banner-settings">查看设置</button>';$('#banner-settings')?.addEventListener('click',()=>setView('settings'));
 $('#week-label').textContent=`第 ${week} 周`;$('#prev-week').disabled=week<=1;$('#next-week').disabled=week>=state.settings.totalWeeks;
 const start=addDays(state.settings.startDate,(week-1)*7),end=addDays(start,6);$('#week-dates').textContent=`${shortDate(start)} — ${shortDate(end)}`;
 const dayCount=$('#show-weekend').checked||weekCourses.some(c=>c.day>5)?7:5;
 let html=`<div class="schedule-grid" style="--days:${dayCount}"><div class="grid-day month">${start.getMonth()+1}月</div>`;
 for(let day=1;day<=dayCount;day++){const d=addDays(start,day-1);html+=`<div class="grid-day ${dateKey(d)===dateKey(now)?'is-today':''}">${DAYS[day-1]}<strong>${d.getDate()}</strong></div>`;}
 for(let period=1;period<=12;period++){html+=`<div class="grid-time" style="grid-column:1;grid-row:${period+1}">${String(period).padStart(2,'0')}<small>${state.settings.times[period-1].split('-')[0]}</small></div>`;for(let day=1;day<=dayCount;day++)html+=`<div class="grid-cell ${dateKey(addDays(start,day-1))===dateKey(now)?'is-today':''}" style="grid-row:${period+1};grid-column:${day+1}"></div>`;}
 for(const c of weekCourses){const peers=weekCourses.filter(other=>other.day===c.day&&other.start<=c.end&&other.end>=c.start);const lane=peers.indexOf(c);html+=`<button class="grid-course ${c.color} ${c.cancelled?'cancelled':c.localOverride?'locally-changed':''} ${week===actual&&clock.current.some(x=>includesSession(c,x))?'is-current':''}" data-course="${esc(c.id)}" data-period="${c.period}" data-end-period="${c.end}" style="grid-column:${c.day+1};grid-row:${c.start+1}/span ${c.end-c.start+1};${peers.length>1?`width:calc(${100/peers.length}% - 4px);margin-left:calc(${100*lane/peers.length}% + 2px);`:''}" aria-label="${esc((c.cancelled?'停课 · ':'')+c.name+' '+DAYS[c.day-1]+' '+periodLabel(c)+' '+c.location)}"><strong>${esc(c.name)}</strong><small>${esc(c.location||'教室待定')}</small>${c.end-c.start>=2?`<small>${esc(c.teacher)}</small>`:''}<span class="course-period">${c.cancelled?'停课':(c.localOverride?'仅本次 · ':'')+periodLabel(c)}</span></button>`;}
 html+='</div>';$('#schedule').innerHTML=html;$('#empty-state').hidden=state.courses.length>0;
 renderToday(todayCourses,mins,clock);renderCourses();if(view==='settings')renderSettings();
}
function renderToday(courses,mins,clock){$('#today-list').innerHTML=courses.length?courses.map(c=>{const start=state.settings.times[c.start-1].split('-')[0],end=state.settings.times[c.end-1].split('-')[1];const toMin=s=>{const [h,m]=s.split(':').map(Number);return h*60+m;};const label=c.cancelled?'停课':mins<toMin(start)?'待上课':mins>=toMin(end)?'已结束':clock.current.some(session=>includesSession(c,session))?'上课中':'课间休息';return `<button class="today-item ${c.cancelled?'cancelled':c.localOverride?'locally-changed':''}" data-course="${esc(c.id)}" data-period="${c.period}" data-end-period="${c.end}"><div class="today-time">${start}<small>${end}</small></div><div class="today-course"><h3>${esc(c.name)}</h3><p>${esc(c.location||'教室待定')} · ${esc(c.teacher||'教师待定')} · ${periodLabel(c)}</p></div><span class="course-badge ${c.color}">${label}</span></button>`;}).join(''):'<div class="empty-card"><div class="empty-icon">☀</div><h2>今天没有课程</h2><p>去图书馆、操场，或者慢慢走一走。</p></div>';}
function renderCourses(){const search=$('#course-search').value.trim().toLowerCase();const list=state.courses.filter(c=>[c.name,c.location,c.teacher].join(' ').toLowerCase().includes(search)).sort((a,b)=>a.day-b.day||a.start-b.start);$('#course-list').innerHTML=list.length?list.map(c=>`<button class="course-row full" data-course="${esc(c.id)}"><span class="course-dot ${c.color}"></span><div><h3>${esc(c.name)}</h3><p>${DAYS[c.day-1]} · ${c.start}—${c.end} 节 · ${esc(c.location||'教室待定')}</p><p>${esc(c.teacher)} ${c.weeks.length} 个上课周</p></div><span class="row-end">编辑 →</span></button>`).join(''):`<div class="empty-card"><h2>${search?'没有找到相关课程':'还没有课程'}</h2><p>${search?'换一个关键词试试。':'可以手动添加，也可以导入教务课表。'}</p></div>`;}
function renderSettings(){const form=$('#settings-form');for(const name of ['term','startDate','totalWeeks'])form.elements[name].value=state.settings[name];$('#time-settings').innerHTML=state.settings.times.map((time,i)=>`<label>第 ${i+1} 节<input name="time-${i}" value="${esc(time)}" required pattern="[0-9]{2}:[0-9]{2}-[0-9]{2}:[0-9]{2}"></label>`).join('');}
function setView(next){view=next;const titles={week:['一周课表','把这一周，安排好。','课程、地点和时间，抬眼就能看到。'],today:['今日安排','今天，也从容一点。','把注意力留给眼前的一堂课。'],courses:['课程管理','每一门课，都有位置。','整理课程、教师、教室和上课周次。'],settings:['学期设置','跟上自己的节奏。','确认学期周次与作息，安排才会准确。']};if(!titles[next])return;for(const id of ['week','today','courses','settings'])$(`#${id}-view`).hidden=id!==next;$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===next));$('#view-title').textContent=titles[next][0];$('#page-title').textContent=titles[next][1];$('#subtitle').textContent=titles[next][2];if(next==='settings')renderSettings();location.hash=next;}
function editCourse(id){const c=state.courses.find(c=>c.id===id);const form=$('#course-form');form.reset();$('#course-error').textContent='';$('#course-dialog-title').textContent=c?'课程详情与编辑':'添加课程';$('#delete-course').hidden=!c;for(const name of ['id','name','day','start','end','location','teacher','note'])form.elements[name].value=c?.[name]??({day:1,start:1,end:2}[name]??'');form.elements.weeks.value=c?c.weeks.join(','):`1-${state.settings.totalWeeks}`;$('#color-options').innerHTML=COLORS.map((color,i)=>`<label class="color-option"><input type="radio" name="color" value="${color}" ${color===(c?.color||COLORS[state.courses.length%COLORS.length])?'checked':''} aria-label="${['绿色','蓝色','橙色','紫色','粉色','黄色'][i]}"><span class="${color}"></span></label>`).join('');showDialog('#course-dialog');}
function openImport(){pendingImport=null;$('#import-text').value='';$('#import-file').value='';$('#import-error').textContent='';$('#import-preview').hidden=true;$('#confirm-import').disabled=true;showDialog('#import-dialog');}
function parseImport(value){try{pendingImport=null;$('#confirm-import').disabled=true;$('#import-preview').hidden=true;$('#import-error').textContent='';const text=typeof value==='string'?value:$('#import-text').value;if(new Blob([text]).size>2*1024*1024)throw Error('文件超过 2 MB');const imported=importData(JSON.parse(text));pendingImport=imported;const count=imported.courses.length;const clash=conflicts(imported.courses).length;$('#import-preview').innerHTML=`<strong>识别到 ${count} 个上课时段</strong><p>来源：${esc(imported.adapter)}${clash?` · ${clash} 组时间冲突`:''}</p><p>${esc(imported.courses.slice(0,5).map(c=>c.name).join('、'))}</p><p>确认后替换当前 ${state.courses.length} 个时段。${imported.settings?'备份中的学期设置也会恢复。':'当前学期设置保留，请确认周次起始日。'}</p>`;$('#import-preview').hidden=false;$('#confirm-import').disabled=false;}catch(e){$('#import-error').textContent=e instanceof SyntaxError?'JSON 格式不完整，请复制完整的响应或选择正确文件。':e.message;}}
function download(content,name,type){if(native&&typeof window.CourseCompass.saveFile==='function'){window.CourseCompass.saveFile(name,type,content);return;}const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));$$('[data-close]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.close).close()));
document.addEventListener('click',event=>{const card=event.target.closest('[data-course]');if(card)editCourse(card.dataset.course);});
$('#prev-week').onclick=()=>{week--;render();};$('#next-week').onclick=()=>{week++;render();};$('#current-week').onclick=()=>{week=Math.max(1,Math.min(state.settings.totalWeeks,weekAt(state.settings.startDate)));render();};$('#show-weekend').onchange=render;
for(const id of ['#add-button','#list-add'])$(id).onclick=()=>editCourse();for(const id of ['#import-button','#empty-import'])$(id).onclick=openImport;
$('#course-search').oninput=renderCourses;
$('#course-form').onsubmit=event=>{event.preventDefault();try{const form=$('#course-form'),raw=Object.fromEntries(new FormData(form));const course=validateCourse(raw,state.courses.length);const courses=state.courses.filter(c=>c.id!==raw.id);courses.push(course);const hasConflict=conflicts(courses).some(pair=>pair.some(c=>c.id===course.id));commit({...state,courses});$('#course-dialog').close();toast(hasConflict?'已保存。该时段与其他课程重叠，请核对。':'课程已保存');}catch(e){$('#course-error').textContent=e.message;}};
$('#delete-course').onclick=()=>{const id=$('#course-form').elements.id.value;$('#course-dialog').close();ask('删除这门课程？','删除后可通过备份恢复。',()=>{commit({...state,courses:state.courses.filter(c=>c.id!==id)});toast('课程已删除');});};
$('#settings-form').onsubmit=event=>{event.preventDefault();try{const form=event.target;const settings=validateSettings({term:form.elements.term.value,startDate:form.elements.startDate.value,totalWeeks:form.elements.totalWeeks.value,times:DEFAULT_TIMES.map((_,i)=>form.elements[`time-${i}`].value.trim())});commit({...state,settings});week=Math.max(1,Math.min(settings.totalWeeks,weekAt(settings.startDate)));render();toast('学期设置已保存');}catch(e){toast(e.message);}};
$('#parse-import').onclick=()=>parseImport();$('#import-text').oninput=()=>{pendingImport=null;$('#confirm-import').disabled=true;$('#import-preview').hidden=true;};$('#import-file').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('文件超过 2 MB');const content=await file.text();$('#import-text').value=content;parseImport(content);}catch(e){$('#import-error').textContent=e.message;}};
$('#confirm-import').onclick=()=>{if(!pendingImport)return;try{commit({version:1,courses:pendingImport.courses,settings:pendingImport.settings||state.settings,demo:pendingImport.demo===true});week=Math.max(1,Math.min(state.settings.totalWeeks,weekAt(state.settings.startDate)));$('#import-dialog').close();setView('week');render();toast('课表已导入，请确认学期日期和作息');}catch(e){$('#import-error').textContent=e.message;}};
$('#export-json').onclick=()=>download(storageError?rawBackup():JSON.stringify(state,null,2),`课间备份-${dateKey()}.json`,'application/json');$('#export-ics').onclick=()=>{if(!state.courses.length){toast('先添加或导入课程');return;}download(toICS(displayCourses().filter(c=>!c.cancelled),state.settings),`课间课表-${dateKey()}.ics`,'text/calendar');};
$('#reset-button').onclick=()=>ask('清空课表？','当前设备的课程会被删除。建议先导出备份。学期设置会保留。',()=>{if(storageError){localStorage.removeItem('course-compass.v1');storageError='';}commit({...state,courses:[],demo:false});toast('已清空课表');});
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();
$('#demo-button').onclick=()=>{try{const base=monday(new Date());base.setDate(base.getDate()-35);const courses=[['高等数学',1,1,2,'A 栋 · 302','陈老师','mint'],['大学英语',1,5,6,'B 栋 · 205','李老师','blue'],['大学物理',2,3,4,'A 栋 · 406','周老师','peach'],['程序设计基础',2,7,8,'实验楼 · 201','张老师','purple'],['高等数学',3,1,2,'A 栋 · 302','陈老师','mint'],['体育',3,7,8,'田径场','林老师','yellow'],['电路基础',4,3,4,'C 栋 · 501','王老师','rose'],['大学英语',4,5,6,'B 栋 · 205','李老师','blue'],['程序设计基础',5,1,2,'实验楼 · 201','张老师','purple'],['大学物理',5,5,6,'A 栋 · 406','周老师','peach']].map(([name,day,start,end,location,teacher,color],i)=>validateCourse({name,day,start,end,location,teacher,color,weeks:'1-20'},i));commit({version:1,demo:true,settings:validateSettings({...state.settings,startDate:dateKey(base),term:'示例学期',totalWeeks:20}),courses});week=6;render();toast('示例已载入，导入真实课表即可替换');}catch(e){toast(e.message);}};
$('#native-import').hidden=!native;$('#web-import').hidden=native;$('#native-open').onclick=()=>window.CourseCompass.openPortal();
window.receiveSchoolData=value=>{if(!$('#import-dialog').open)openImport();$('#import-text').value=typeof value==='string'?value:JSON.stringify(value);parseImport($('#import-text').value);};
window.onNativeExportResult=message=>toast(message);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installEvent=event;});$('#install-button').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;}else{toast(native?'课间 0.5.1':'在安卓 Chrome 菜单中选择「添加到主屏幕」或「安装应用」');}};
window.addEventListener('online',()=>$('#connection').textContent='课表保存在此设备');window.addEventListener('offline',()=>$('#connection').textContent='离线查看已就绪');
if('serviceWorker' in navigator&&!native)navigator.serviceWorker.register('./sw.js').catch(()=>console.info('当前浏览器未启用离线缓存'));
setInterval(()=>{if(!$$('dialog').some(d=>d.open)&&view!=='settings')render();},60000);
render();setView(['week','today','courses','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'week');

function syncNativeCompanion(){if(!window.CourseCompass?.updateSchedule||storageError)return;try{const personal=JSON.parse(localStorage.getItem('course-compass.demo.personal')||'[]').map((c,i)=>({...validateCourse(c,i),personal:true}));window.CourseCompass.updateSchedule(JSON.stringify({...state,courses:displayCourses([...(state.demo?[]:state.courses),...personal]).filter(c=>!c.cancelled)}));}catch{}}
syncNativeCompanion();
